func TestDatParseAndRoundTrip(t *testing.T) {
	for _, tc := range datPackets {
		t.Run(tc.name, func(t *testing.T) {
			got := parseAndCompare(t, tc.hex, tc.want)
			serializeRoundTrip(t, got, tc.hex)
		})
	}
}

